SELECT 


    ts.project_id = #{projectId}
    AND ts.user_id = #{userId}
    AND ts.status = #{status}
    AND ts.work_date >= #{beginDate}
    AND ts.work_date <= #{endDate}

ORDER BY ts.work_date DESC, ts.id DESC

SELECT 

WHERE ts.user_id = #{userId} AND ts.work_date BETWEEN #{beginDate} AND #{endDate}
ORDER BY ts.work_date, ts.id

SELECT COALESCE(SUM(hours), 0) FROM pm_timesheet
WHERE user_id = #{userId} AND work_date = #{workDate} AND status <> 'REJECTED'
AND id <> #{excludeId}
